use std::collections::BTreeMap;
use std::io::Read;

fn main() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut bad = 0u64;
    let mut m: BTreeMap<String, (u64, u128, BTreeMap<String, u64>)> = BTreeMap::new();
    for line in s.lines() {
        let t: Vec<&str> = line.split_whitespace().collect();
        if t.len() != 3 || t[2].is_empty() || !t[2].bytes().all(|b| b.is_ascii_digit()) {
            bad += 1;
            continue;
        }
        let v: u128 = match t[2].parse() {
            Ok(v) => v,
            Err(_) => {
                bad += 1;
                continue;
            }
        };
        let e = m.entry(t[0].to_string()).or_insert((0, 0, BTreeMap::new()));
        e.0 += 1;
        e.1 += v;
        *e.2.entry(t[1].to_string()).or_insert(0) += 1;
    }
    let mut v: Vec<_> = m.into_iter().collect();
    v.sort_by(|a, b| b.1 .1.cmp(&a.1 .1).then(a.0.cmp(&b.0)));
    for (name, (c, tot, acts)) in v {
        let mut best: Option<(&String, u64)> = None;
        for (a, n) in &acts {
            if best.map_or(true, |(_, bn)| *n > bn) {
                best = Some((a, *n));
            }
        }
        println!("{} {} {} {}", name, c, tot, best.unwrap().0);
    }
    println!("malformed: {}", bad);
}

